import Generator from 'yeoman-generator';
import chalk from 'chalk';

export default class extends Generator {
  async prompting() {
    this.answers = await this.prompt([
      {
        type: 'input',
        name: 'projectName',
        message: 'Project name:',
        default: this.appname
      },
      {
        type: 'list',
        name: 'projectType',
        message: 'Project type:',
        choices: ['React SPA', 'Node API', 'Full Stack', 'Micro-Frontend']
      }
    ]);
  }

  writing() {
    const { projectName, projectType } = this.answers;

    this.fs.copyTpl(
      this.templatePath('**/*'),
      this.destinationPath(projectName),
      { projectName, projectType }
    );
  }

  install() {
    this.npmInstall();
  }
}

// amcli generate component Button --type=functional --tests

import { GeneratorCommand } from './base';

export class ComponentGenerator extends GeneratorCommand {
  async execute(name: string, options: ComponentOptions) {
    const template = options.type === 'class' 
      ? this.getClassTemplate()
      : this.getFunctionalTemplate();

    await this.createFile(
      `src/components/${name}/${name}.tsx`,
      template.replace('{{name}}', name)
    );

    if (options.tests) {
      await this.createFile(
        `src/components/${name}/${name}.test.tsx`,
        this.getTestTemplate(name)
      );
    }

    this.log(chalk.green(`✓ Component ${name} created successfully`));
  }
}

